pm.test("Статус 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Ответ быстрее 5000 мс", function () {
    pm.expect(pm.response.responseTime).to.be.below(5000);
});

pm.test("На главной есть название магазина", function () {
    pm.expect(pm.response.text()).to.include("Aloha");
});

// достаём csrf_token из HTML (порядок атрибутов в теге заранее неизвестен)
const html = pm.response.text();
const m = html.match(/name=["']csrf_token["'][^>]*value=["']([^"']+)["']/i)
       || html.match(/value=["']([^"']+)["'][^>]*name=["']csrf_token["']/i);
if (m) {
    pm.collectionVariables.set("csrf_token", m[1]);
}

pm.test("На главной найден csrf_token", function () {
    pm.expect(m, "токен не найден в HTML").to.not.be.null;
});

// берём первый товар и, если у него есть размеры, первый доступный размер
const mp = html.match(/name=["']product_id["'][^>]*value=["'](\d+)["']/i)
        || html.match(/value=["'](\d+)["'][^>]*name=["']product_id["']/i);
let size = "";
if (mp) {
    const rest = html.slice(html.indexOf(mp[0]));
    const form = rest.split("</form>")[0];
    // доступный размер: <option value="M" > без слова disabled
    const ms = form.match(/<option value="([^"]+)"\s*>/i);
    if (ms) { size = ms[1]; }
    pm.collectionVariables.set("product_id", mp[1]);
    pm.collectionVariables.set("size", size);
}

pm.test("На главной найден доступный товар", function () {
    pm.expect(mp, "product_id не найден в HTML").to.not.be.null;
});

